def _pk(brand, cats, prods, f4, st, ts, off, faq, about, hours, addr, mq, dc, dp, **o):
    d = dict(brand=brand, cats_t=cats[0], cats_s=cats[1], prods_t=prods[0], prods_s=prods[1], about=about, mq=mq, off_h=off[0], off_p=off[1], off_cp=off[2], hours=hours, addr=addr, dc=dc, dp=dp)
    for i, (t, x) in enumerate(f4): d["f%dt" % i] = t; d["f%dx" % i] = x
    for i, v in enumerate(st): d["st%d" % i] = v
    for i, (n, c, x) in enumerate(ts): d["t%dn" % i] = n; d["t%dc" % i] = c; d["t%dx" % i] = x
    for i, (q, a) in enumerate(faq): d["q%d" % i] = q; d["a%d" % i] = a
    d.update(o); return d
def _P(t, p, old, img, cat=""): return dict(t=t, p=p, o=old, i="assets/img/tpl/%s.webp" % img, c=cat)

